/**
 * QNBS-v3: API-key resolution for local OpenAI-compatible servers.
 *
 * Unsloth Studio exposes an authenticated OpenAI-compatible API (Bearer key generated by the
 * app). Ollama, LM Studio and vLLM stay keyless, so this module only touches storage for the
 * presets that actually need a credential — a missing key degrades to an unauthenticated request
 * instead of blocking the call, and the server's own 401 surfaces through the normal HTTP error
 * path.
 */

import type { LocalBackendPreset } from '../../types';
import { storageService } from '../storageService';

/** Storage slot name used by `storageService.saveApiKey` for the Unsloth server key. */
export const UNSLOTH_API_KEY_SLOT = 'unsloth';

export function localBackendApiKeySlot(
  preset: LocalBackendPreset | undefined,
): typeof UNSLOTH_API_KEY_SLOT | null {
  return preset === 'unsloth' ? UNSLOTH_API_KEY_SLOT : null;
}

export async function resolveLocalBackendApiKey(
  preset: LocalBackendPreset | undefined,
): Promise<string | null> {
  const slot = localBackendApiKeySlot(preset);
  if (!slot) return null;
  try {
    const key = await storageService.getApiKey(slot);
    return key?.trim() ? key.trim() : null;
  } catch {
    // QNBS-v3: a locked/unavailable key store must not turn a local request into a hard failure.
    return null;
  }
}
